SELECT tgr.id AS id, tgr.group_id AS groupId, tgr.rater_id AS raterId, tgr.rater_type AS raterType, tgr.coop_user_id AS coopUserId, tgr.coop_user_name AS coopUserName, tgr.rating_details AS ratingDetails, tgr.avg_rating AS avgRating, tgr.gmt_created AS gmtCreated, tcg.department_id AS departmentCode, tge.archived AS archived, tag.tag_id AS tagId, tag.tag_name AS tagName FROM tb_group_rating tgr LEFT JOIN tb_create_group tcg ON tgr.group_id = tcg.group_id LEFT JOIN tb_group_extends tge ON tgr.group_id = tge.group_id
LEFT JOIN LATERAL ( SELECT tgt.tag_id, tt.name AS tag_name FROM tb_group_tag tgt LEFT JOIN tb_tags tt ON tgt.tag_id = tt.id AND tt.deleted = 0 WHERE tgt.group_id = tgr.group_id AND tgt.is_deleted = 0 ) tag ON TRUE
tge.archived = 2
